// Dependency: no field, just a parameter. Weakest coupling.
class Printer {
    void print(Receipt receipt) { System.out.println(receipt.total()); }
}

// Association: holds a reference, but does not own the peer.
class Driver {
    private Car car; // injected, may be swapped
    Driver(Car car) { this.car = car; }
    void drive() { car.move(); }
}

// Aggregation: collects pre-existing parts. Never creates or deletes them.
class Garage {
    private final List<Car> slots = new ArrayList<>();
    void park(Car car) { slots.add(car); }      // car lives on after garage closes
    void unpark(Car car) { slots.remove(car); }
}

// Composition: creates, hides, and owns the part. No escape.
class Car {
    private final Engine engine; // private + final + no getter = ownership
    Car(String spec) { this.engine = new Engine(spec); }
    void move() { engine.ignite(); }
}

// Realization: program to the interface, compose the implementation.
interface BlobStore { void put(String k, byte[] v); }
class OrderService {
    private final BlobStore store; // association to abstraction, not concretion
    OrderService(BlobStore store) { this.store = store; }
}
